package com.ruoyi.library.service;
import com.ruoyi.common.exception.ServiceException;import com.ruoyi.library.domain.*;import com.ruoyi.library.dto.CourseCodeBatchResult;import com.ruoyi.library.mapper.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.NoSuchAlgorithmException;import java.security.SecureRandom;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
/** 高熵课程码批量生成和永久授权兑换服务。 */
@Service public class CourseCodeService
{private static final char[] ALPHABET="23456789ABCDEFGHJKLMNPQRSTUVWXYZ".toCharArray();private static final int CODE_LENGTH=16;private final WlCourseCodeMapper codeMapper;private final WlUserCourseMapper grantMapper;private final WlCourseMapper courseMapper;private final WlWxUserMapper userMapper;private final SecureRandom random=new SecureRandom();public CourseCodeService(WlCourseCodeMapper c,WlUserCourseMapper g,WlCourseMapper m,WlWxUserMapper u){codeMapper=c;grantMapper=g;courseMapper=m;userMapper=u;}
@Transactional public CourseCodeBatchResult generate(Long courseId,int count,Date expires,String operator){WlCourse course=requireCodeCourse(courseId);if(count<1||count>1000)throw new ServiceException("单批兑换码数量必须在1到1000之间");String batch="CB"+UUID.randomUUID().toString().replace("-","");List<String> plain=new ArrayList<>();for(int i=0;i<count;i++){String code=nextUniqueCode();WlCourseCode row=new WlCourseCode();row.setCourseId(course.getId());row.setCodeDigest(digest(code));row.setCodeMask("****"+code.substring(code.length()-4));row.setStatus("UNUSED");row.setExpiresTime(expires);row.setBatchNo(batch);row.setCreateBy(operator);if(codeMapper.insertCode(row)!=1)throw new ServiceException("课程码生成失败，请重试");plain.add(code);}return new CourseCodeBatchResult(batch,plain);}
@Transactional public WlUserCourse redeem(Long userId,String plaintext){requireEnabledUser(userMapper.selectById(userId));String hash=digest(normalize(plaintext));WlCourseCode summary=codeMapper.selectByDigest(hash);if(summary==null)throw new ServiceException("课程码不存在");WlUserCourse owned=grantMapper.selectByUserCourse(userId,summary.getCourseId());if(owned!=null)return owned;WlCourseCode code=codeMapper.selectByDigestForUpdate(hash);if(code==null)throw new ServiceException("课程码不存在");owned=grantMapper.selectByUserCourse(userId,code.getCourseId());if(owned!=null)return owned;if(!"UNUSED".equals(code.getStatus()))throw new ServiceException("课程码已被使用");if(code.getExpiresTime()!=null&&!code.getExpiresTime().after(new Date()))throw new ServiceException("课程码已过期");requireCodeCourse(code.getCourseId());WlUserCourse grant=new WlUserCourse();grant.setUserId(userId);grant.setCourseId(code.getCourseId());grant.setCourseCodeId(code.getId());grant.setAccessSource("CODE");grant.setPermanent("1");grant.setGrantedTime(new Date());grant.setCreateBy(String.valueOf(userId));if(grantMapper.insertGrant(grant)!=1||codeMapper.markUsed(code.getId(),userId)!=1)throw new ServiceException("课程码兑换失败，请重试");return grant;}
public List<WlCourseCode> list(WlCourseCode q){return codeMapper.selectList(q==null?new WlCourseCode():q);}private WlCourse requireCodeCourse(Long id){WlCourse c=courseMapper.selectById(id);if(c==null||!"0".equals(c.getStatus()))throw new ServiceException("课程不存在或已停用");if(!"CODE".equals(c.getAccessType()))throw new ServiceException("该课程不支持课程码兑换");return c;}private void requireEnabledUser(WlWxUser u){if(u==null)throw new ServiceException("微信用户不存在");if(!"0".equals(u.getStatus()))throw new ServiceException("当前账号已停用，请联系管理员");}private String nextUniqueCode(){for(int n=0;n<10;n++){StringBuilder b=new StringBuilder(CODE_LENGTH);for(int i=0;i<CODE_LENGTH;i++)b.append(ALPHABET[random.nextInt(ALPHABET.length)]);String code=b.toString();if(codeMapper.selectByDigest(digest(code))==null)return code;}throw new ServiceException("课程码生成冲突，请重试");}private String normalize(String s){if(s==null||s.trim().isEmpty())throw new ServiceException("课程码不能为空");String v=s.trim().toUpperCase(Locale.ROOT);if(v.length()<8||v.length()>32)throw new ServiceException("课程码格式不正确");return v;}private String digest(String s){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder(64);for(byte v:bytes)b.append(String.format("%02x",v&255));return b.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException("系统不支持 SHA-256",e);}}}
